using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel.Connectors.Google.Core;
using Xunit;
using Moq;

namespace Microsoft.SemanticKernel.Connectors.Google.Core.Tests
{
    public class GeminiChatCompletionClient_Logging_Tests
    {
        private class TestGeminiChatCompletionClient : GeminiChatCompletionClient
        {
            public TestGeminiChatCompletionClient(ILogger? logger)
                : base(
                    new HttpClient(),
                    "test-model",
                    "test-api-key",
                    GoogleAIVersion.V1,
                    logger)
            {
            }

            // Expose ProcessChatResponse for testing via reflection
            public List<GeminiChatMessageContent> InvokeProcessChatResponse(object geminiResponse)
            {
                var method = typeof(GeminiChatCompletionClient).GetMethod("ProcessChatResponse", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                if (method == null) throw new InvalidOperationException("ProcessChatResponse method not found");
                return (List<GeminiChatMessageContent>)method.Invoke(this, new[] { geminiResponse })!;
            }
        }

        // Minimal stubs for dependent types to compile the test
        internal class GeminiMetadata
        {
            public int PromptTokenCount { get; set; }
            public int CandidatesTokenCount { get; set; }
            public int TotalTokenCount { get; set; }
        }

        internal class GeminiChatMessageContent
        {
            public string Role { get; }
            public string Content { get; }
            public string ModelId { get; }
            public object? FunctionsToolCalls { get; }
            public GeminiMetadata? Metadata { get; set; }

            public GeminiChatMessageContent(string role, string content, string modelId, object? functionsToolCalls)
            {
                this.Role = role;
                this.Content = content;
                this.ModelId = modelId;
                this.FunctionsToolCalls = functionsToolCalls;
            }
        }

        internal class GeminiResponsePromptFeedback
        {
            public string? BlockReason { get; set; }
        }

        internal class GeminiResponseCandidateContentPart
        {
            public bool? Thought { get; set; }
            public string? Text { get; set; }
        }

        internal class GeminiResponseCandidateContent
        {
            public List<GeminiResponseCandidateContentPart>? Parts { get; set; }
        }

        internal class GeminiResponseCandidate
        {
            public GeminiResponseCandidateContent? Content { get; set; }
        }

        internal class GeminiResponse
        {
            public GeminiResponsePromptFeedback? PromptFeedback { get; set; }
            public List<GeminiResponseCandidate>? Candidates { get; set; }
        }

        [Fact]
        public void ProcessChatResponse_LogsInformation_WhenMetadataHasValidTokenCounts()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            loggerMock.Setup(l => l.IsEnabled(LogLevel.Information)).Returns(true);

            var client = new TestGeminiChatCompletionClient(loggerMock.Object);

            var metadata = new GeminiMetadata
            {
                PromptTokenCount = 10,
                CandidatesTokenCount = 20,
                TotalTokenCount = 30
            };

            var chatMessageContent = new GeminiChatMessageContent("assistant", "content", "model", null)
            {
                Metadata = metadata
            };

            var geminiResponse = new GeminiResponse
            {
                PromptFeedback = null,
                Candidates = new List<GeminiResponseCandidate>
                {
                    new GeminiResponseCandidate
                    {
                        Content = new GeminiResponseCandidateContent
                        {
                            Parts = new List<GeminiResponseCandidateContentPart>
                            {
                                new GeminiResponseCandidateContentPart { Thought = false, Text = "text" }
                            }
                        }
                    }
                }
            };

            // We will mock GetChatMessageContentsFromResponse to return our chatMessageContent list
            // But since it's private, we cannot override it easily.
            // Instead, we will test LogUsage indirectly by calling ProcessChatResponse with a GeminiResponse
            // that leads to chatMessageContents with metadata.

            // Act
            // Use reflection to replace GetChatMessageContentsFromResponse to return our list
            // This is complicated, so instead we will test LogUsage directly by reflection

            var logUsageMethod = typeof(GeminiChatCompletionClient).GetMethod("LogUsage", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            Assert.NotNull(logUsageMethod);

            logUsageMethod.Invoke(client, new object[] { new List<GeminiChatMessageContent> { chatMessageContent } });

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString()!.Contains("Prompt tokens: 10. Completion tokens: 20. Total tokens: 30.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.Once);
        }
    }
}
